import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import EntryCard from './EntryCard';
import ListCard from './ListCard';
import ListEditModal from './ListEditModal';
import { t, curioHandlesCollections } from '../util';
const FILTERS = ['all', 'rated', 'done', 'want', 'owned'];

/** The collection filter steps aside when Curio holds collections. */
const filters = () => curioHandlesCollections() ? FILTERS.filter(key => key !== 'owned') : FILTERS;
const PAGE = 24;

/** A member's shelf: their lists, then everything they rated or logged. */
export default class ShelfPage extends UserPage {
  filter = 'all';
  entries = [];
  lists = null;
  loading = true;
  more = false;
  shownFor = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    if (this.shownFor === user.id()) return;
    this.shownFor = user.id() ?? null;
    app.store.find('shelf-lists', {
      filter: {
        user: user.id()
      },
      page: {
        limit: 50
      }
    }).then(lists => {
      this.lists = lists;
      m.redraw();
    }, () => {
      // app.request already showed the alert; stop the spinner.
      this.lists = [];
      m.redraw();
    });
    this.load(true);
  }
  load(reset) {
    if (reset) {
      this.entries = [];
      this.more = false;
    }
    this.loading = true;
    const filter = {
      user: this.user.id()
    };
    if (this.filter !== 'all') filter.status = this.filter;
    return app.store.find('shelf-entries', {
      filter,
      page: {
        offset: this.entries.length,
        limit: PAGE
      }
    }).then(entries => {
      this.entries.push(...entries);
      this.more = !!entries.payload?.links?.next;
      this.loading = false;
      m.redraw();
    }, () => {
      // app.request already showed the alert; stop the spinner.
      this.loading = false;
      m.redraw();
    });
  }
  content() {
    const own = app.session.user === this.user;
    return m("div", {
      className: "ShelfPage"
    }, this.listsSection(own), this.entriesSection(own));
  }
  listsSection(own) {
    return m("section", {
      className: "ShelfPage-lists"
    }, m("div", {
      className: "ShelfPage-heading"
    }, m("h2", null, t('profile.lists_heading')), own && app.forum.attribute('canUseShelf') ? m(Button, {
      className: "Button",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(ListEditModal, {
        onsave: list => m.route.set(app.route('shelf.list', {
          id: list.id()
        }))
      })
    }, t('lists.new_button')) : null), this.lists === null ? m(LoadingIndicator, {
      display: "block"
    }) : this.lists.length ? m("ul", {
      className: "ShelfListCards"
    }, this.lists.map(ListCard)) : m("p", {
      className: "ShelfPage-none"
    }, t(own ? 'profile.no_lists_own' : 'profile.no_lists')));
  }
  entriesSection(own) {
    return m("section", {
      className: "ShelfPage-entries"
    }, m("div", {
      className: "ShelfPage-heading"
    }, m("h2", null, t('profile.shelf_heading')), m("div", {
      className: "ButtonGroup ShelfPage-filters",
      role: "group"
    }, filters().map(key => m(Button, {
      className: this.filter === key ? 'Button Button--primary' : 'Button',
      "aria-pressed": this.filter === key ? 'true' : 'false',
      onclick: () => {
        if (this.filter === key) return;
        this.filter = key;
        this.load(true);
      }
    }, t(`profile.filter_${key}`))))), this.entries.length ? m("ul", {
      className: "ShelfCards"
    }, this.entries.map(EntryCard)) : null, this.loading ? m(LoadingIndicator, {
      display: "block"
    }) : !this.entries.length ? m(Placeholder, {
      text: t(own ? 'profile.empty_own' : 'profile.empty')
    }) : this.more ? m("div", {
      className: "ShelfPage-more"
    }, m(Button, {
      className: "Button",
      onclick: () => this.load(false)
    }, t('profile.load_more'))) : null);
  }
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/ShelfPage', ShelfPage);