import { mediaPoster } from './Poster';
import Stars from './Stars';
import { t, verb, date, titleOf, curioHandlesCollections } from '../util';

/** One title on a member's shelf: poster, name, their stars and when they got to it. */
export default function EntryCard(entry) {
  const media = entry.media();
  if (!media) return null;
  const v = verb(media.kind());
  const status = entry.status();
  return m("li", {
    className: "ShelfCard"
  }, mediaPoster(media, titleOf(media)), m("div", {
    className: "ShelfCard-body"
  }, m("b", {
    className: "ShelfCard-title"
  }, titleOf(media)), entry.rating() ? m(Stars, {
    value: entry.rating(),
    size: "small"
  }) : null, entry.owned() && !curioHandlesCollections() ? m("span", {
    className: "ShelfCard-status ShelfCard-status--owned"
  }, m("i", {
    className: "fas fa-box-archive",
    "aria-hidden": "true"
  }), " ", t('status.owned')) : null, status ? m("span", {
    className: `ShelfCard-status ShelfCard-status--${status}`
  }, status === 'done' && entry.doneOn() ? t(`card.done_on_${v}`, {
    date: date(entry.doneOn())
  }) : t(`status.${status}_${v}`)) : null));
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/EntryCard', EntryCard);